.scada-container-fixed {
    width: 100%;
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    background: #f8f9fa; /* Виджетийн арын дэвсгэр өнгө */
    overflow: hidden;
    box-sizing: border-box;
}

/* Зурагтай яг ижил хэмжээтэйгээр хавчигдах үндсэн хавтас */
.scada-wrapper {
    position: relative;
    display: inline-block;
    max-width: 100%;
    max-height: 100%;
}

/* Зургийн тохиргоо - Өндөр, өргөнийг харьцаагаар нь автоматаар барина */
.scada-bg {
    display: block;
    max-width: 100%;
    max-height: 100vh; /* Виджетийн өндрөөс хэтрэхгүй */
    width: auto;
    height: auto;
    object-fit: contain;
}

/* Мэдрэгчийн хайрцагны ерөнхий загвар */
.sensor-badge {
    position: absolute;
    background: rgba(255, 255, 255, 0.92);
    border: 1px solid #b0bec5;
    border-radius: 4px;
    padding: 4px 8px;
    font-family: Arial, sans-serif;
    font-size: 12px;
    font-weight: bold;
    color: #263238;
    box-shadow: 0 3px 6px rgba(0,0,0,0.16);
    white-space: nowrap;

    /* Хайрцагны яг төв цэгийг (%) координат дээр зоож өгнө */
    transform: translate(-50%, -50%); 
    z-index: 10;
}

.sensor-badge .title {
    font-size: 9px;
    color: #607d8b;
    border-bottom: 1px solid #cfd8dc;
    margin-bottom: 3px;
    padding-bottom: 2px;
    text-align: center;
}

.value-row {
    margin: 2px 0;
}

/* =======================================================
   БАЙРШИЛ ОДОО ЯГ ТАГ ЗУРГИЙН ИРМЭГЭЭС ТООЦОГДОНО 
   ======================================================= */
.line-fac-out {
    top: 50%;  /* Зургийн дээрээс 25% */
    left: 80%; /* Зургийн зүүн талаас 80% */
    border-left: 3px solid #0077b6;

}

.line-fac-in {
    top: 20%;  /* Зургийн дээрээс 25% */
    left: 50%; /* Зургийн зүүн талаас 20% */
    border-left: 3px solid #d90429;

}

.line-cus-out {
    top: 90%;  /* Зургийн дээрээс 65% */
    left: 50%; /* Зургийн зүүн талаас 80% */
    border-left: 3px solid #03045e;

}

.line-cus-in {
    top: 65%;  /* Зургийн дээрээс 65% */
    left: 20%; /* Зургийн зүүн талаас 20% */
    border-left: 3px solid #ef233c;
}

descriptor.controllerScript:
self.onInit = function() {
    // Анхны эхлүүлэлт
};

self.onDataUpdated = function() {
    if (self.ctx.data && self.ctx.data.length > 0) {

        for (var i = 0; i < self.ctx.data.length; i++) {
            var datasourceData = self.ctx.data[i];

            if (datasourceData.dataKey && datasourceData.dataKey.name) {
                var dataKey = datasourceData.dataKey.name;

                if (datasourceData.data && datasourceData.data.length > 0) {
                    var latestPoint = datasourceData.data[datasourceData.data.length - 1];
                    var rawValue = "";

                    // 1. Хэрэв массив байвал түүнийг текст рүү хөрвүүлнэ
                    if (Array.isArray(latestPoint)) {
                        rawValue = latestPoint.join(',');
                    } else if (latestPoint !== undefined && latestPoint !== null) {
                        rawValue = latestPoint.toString();
                    }

                    // 2. ТЕКСТИЙГ ХЭРЧИЖ БОДИТ УТГЫГ САНАМСАРГҮЙ БИШ, ЯГ ТАГ ШҮҮХ
                    if (rawValue.includes(',')) {
                        var parts = rawValue.split(',');

                        for (var p = 0; p < parts.length; p++) {
                            var item = parts[p].trim();

                            // Нөхцөл: Хоосон биш, тоо мөн, БӨГӨӨД 1000000000-аас бага (Timestamp биш) утгыг хайна
                            if (item !== "" && !isNaN(item)) {
                                var numCheck = Number(item);
                                if (numCheck < 1000000000) { 
                                    rawValue = item; // Эндээс яг 77.97 гэсэн утгыг барьж авна
                                    break;
                                }
                            }
                        }
                    }

                    // 3. Цэвэр тоо руу хөрвүүлж форматлах
                    var numericValue = Number(rawValue);
                    var formattedValue = '--';
                    console.log(numericValue)
                    if (!isNaN(numericValue) && rawValue !== "") {
                        var decimals = datasourceData.dataKey.decimals !== undefined ? datasourceData.dataKey.decimals : 1;
                        var units = datasourceData.dataKey.units ? ' ' + datasourceData.dataKey.units : '';
                        formattedValue = numericValue.toFixed(decimals) + units;
                    } else if (rawValue !== undefined && rawValue !== null) {
                        formattedValue = rawValue.toString();
                    }

                    // 4. HTML дээрх харгалзах ID руу утгыг шахах
                    var element = self.ctx.$container.find('#' + dataKey);
                    if (element && element.length > 0) {
                        element.text(formattedValue);
                    }
                }
            }
        }
    }
};

/* Сүүлийн хувилбарын олон дата хүлээж авах тохиргоо */
self.typeParameters = function() {
    return {
        maxDatasources: 1,
        maxDataKeys: 10,
        singleEntity: true
    };
};

self.onDestroy = function() {
};

